  --request-id 'midnight-sleeper-train-decision-brief-20260730-v1' \\
  --intent 'Build a polished editable decision brief for a midnight sleeper-train launch with the decision, three real tradeoffs, a recommendation, key evidence, and two immediate next actions.' \\
  --plan-file - \\
  --json <<'JSON'
{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"title\",
      \"recipe\": {
        \"kind\": \"native_text\",
        \"text\": \"MIDNIGHT SLEEPER TRAIN\\nLaunch decision brief · Recovery stage 2\",
        \"placement\": {
          \"target\": { \"kind\": \"auto\" }
        }
      }
    },
    {
      \"alias\": \"decision\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"DECISION · Launch, but stage the commitment\",
        \"body\": \"Approve a 90-day, four-night-per-week midnight sleeper pilot. Do not open daily service until demand, punctuality, and berth economics clear explicit gates. Keep a no-launch option if operating readiness is not signed.\"
      }
    },
    {
      \"alias\": \"recommended\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"RECOMMENDED OPTION · Controlled 00:05 pilot\",
        \"body\": \"Run Thursday–Sunday with a mixed cabin/couchette offer, capped inventory, flexible pricing, and a morning-arrival promise. Review at weeks 2, 6, and 12; expand only when the evidence supports it.\"
      }
    },
    {
      \"alias\": \"evidence\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"KEY EVIDENCE & DECISION GATES\",
        \"body\": \"• Customer value: overnight rail combines travel with one hotel night and preserves a full daytime schedule.\\n• Measure paid conversion and cabin mix—not clicks or waitlist size alone.\\n• Require signed platform, cleaning, crew-rest, security, and disruption-recovery plans before sales.\\n• Expansion gates: ≥70% occupancy by week 6, ≥85% on-time morning arrival, positive contribution per departure, and stable service-recovery cost.\"
      }
    },
    {
      \"alias\": \"tradeoff_demand\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"TRADEOFF 1 · Useful timing vs station access\",
        \"body\": \"A 00:05 departure preserves the evening and supports morning arrival, but late public transport, station staffing, safety, and missed-connection recovery can suppress demand. Mitigation: target stations with late access and sell protected connections.\"
      }
    },
    {
      \"alias\": \"tradeoff_product\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"TRADEOFF 2 · Sleep quality vs sellable capacity\",
        \"body\": \"Private cabins improve rest, privacy, and yield, but reduce passenger density. Couchettes widen the price ladder but raise noise and service complexity. Mitigation: start with a measured mixed-berth inventory and reallocate from booking data.\"
      }
    },
    {
      \"alias\": \"tradeoff_ops\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"TRADEOFF 3 · Network reach vs reliability\",
        \"body\": \"More stops and daily frequency improve convenience, yet compress maintenance, cleaning, crew, and recovery windows. One poor night damages a sleep product disproportionately. Mitigation: four-night launch, limited stops, protected turnaround, and spare capacity.\"
      }
    },
    {
      \"alias\": \"action_one\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"NEXT ACTION 1 · 48 hours\",
        \"body\": \"Name one accountable launch lead and freeze the pilot route, four-night timetable, berth mix, readiness checklist, and week-6 expansion gates.\"
      }
    },
    {
      \"alias\": \"action_two\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"NEXT ACTION 2 · 7 days\",
        \"body\": \"Open a refundable paid-reservation test by berth type while operations completes a tabletop disruption drill. Return with conversion, projected contribution, and the signed go/no-go gaps.\"
      }
    }
  ],
  \"connections\": [
    {
      \"kind\": \"visual\",
      \"label\": \"weighs\",
      \"source\": { \"alias\": \"decision\" },
      \"target\": { \"alias\": \"tradeoff_demand\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"weighs\",
      \"source\": { \"alias\": \"decision\" },
      \"target\": { \"alias\": \"tradeoff_product\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"weighs\",
      \"source\": { \"alias\": \"decision\" },
      \"target\": { \"alias\": \"tradeoff_ops\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"supports\",
      \"source\": { \"alias\": \"evidence\" },
      \"target\": { \"alias\": \"recommended\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"activates\",
      \"source\": { \"alias\": \"recommended\" },
      \"target\": { \"alias\": \"action_one\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"activates\",
      \"source\": { \"alias\": \"recommended\" },
      \"target\": { \"alias\": \"action_two\" }
    }
  ],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": { \"alias\": \"title\" },
    \"members\": [
      \"decision\",
      \"recommended\",
      \"evidence\",
      \"tradeoff_demand\",
      \"tradeoff_product\",
      \"tradeoff_ops\",
      \"action_one\",
      \"action_two\"
    ],
    \"columns\": 3,
    \"column_gap\": 56,
    \"row_gap\": 56,
    \"align\": \"start\",
    \"placement\": {
      \"clearance\": 88,
      \"preferred_directions\": [\"below\"]
    }
  }
}
JSON"

